const item = $input.first();

// n8n can place multipart form fields inside body.
// Keep fallbacks so we can see exactly what arrived.
const body = item.json.body || item.json;

const user_id = body.user_id;
const report_type = body.report_type;
const report_date = body.report_date;

const binaryKeys = item.binary
  ? Object.keys(item.binary)
  : [];

const fileKey = item.binary?.file
  ? 'file'
  : binaryKeys.length > 0
    ? binaryKeys[0]
    : null;

const missing = [];

if (!user_id) missing.push('user_id');
if (!report_type) missing.push('report_type');
if (!report_date) missing.push('report_date');
if (!fileKey) missing.push('file');

if (missing.length > 0) {
  return [
    {
      json: {
        valid: false,
        error: `Missing: ${missing.join(', ')}`,

        // DEBUG INFORMATION
        received_body: body,
        received_json: item.json,
        received_binary_keys: binaryKeys
      },
      binary: item.binary
    }
  ];
}

return [
  {
    json: {
      valid: true,
      user_id: String(user_id).trim(),
      report_type: String(report_type).trim(),
      report_date: String(report_date).trim()
    },
    binary: {
      file: item.binary[fileKey]
    }
  }
];

// ============================================================
// RESTORE FILE + DETERMINE WHETHER USER EXISTS
// ============================================================

const userCheck = $input.first();
const originalRequest = $('Validate Request').first();

// Check original uploaded file
if (!originalRequest.binary?.file) {
  throw new Error(
    'Uploaded file was not found in "Validate Request". Expected binary.file.'
  );
}

// Supabase response
const result = userCheck.json;

// Supabase REST normally returns an array
const users = Array.isArray(result)
  ? result
  : [result];

// Determine whether a user was found
const userFound = users.length > 0 && !!users[0]?.user_id;

// Get original request information
const originalData = originalRequest.json;

// Return everything needed downstream
return [
  {
    json: {
      valid: true,
      user_found: userFound,

      user_id: originalData.user_id,
      report_type: originalData.report_type,
      report_date: originalData.report_date,

      ...(userFound
        ? {
            verified_user_id: users[0].user_id
          }
        : {})
    },

    binary: {
      file: originalRequest.binary.file
    }
  }
];

const res = $input.first().json;
const validated = $('Validate Request').first().json;
if (res.IsErroredOnProcessing) {
  return [{ json: { ocrFailed: true, error: (res.ErrorMessage || ['OCR failed']).join('; '), ...validated } }];
}
const parsedText = (res.ParsedResults || []).map(r => r.ParsedText || '').join('\n').trim();
if (!parsedText) {
  return [{ json: { ocrFailed: true, error: 'OCR returned no text (image may be too low quality)', ...validated } }];
}
return [{ json: { ocrFailed: false, ocr_text: parsedText, ...validated } }];

// Get the input from Gemini
const item = $input.first();

// Gemini response text
const text =
  item.json.candidates?.[0]?.content?.parts?.[0]?.text || '';

if (!text) {
  throw new Error('Gemini returned no text');
}

// Remove markdown code fences if Gemini added them
let cleanText = text
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

// Extract JSON object if there is extra text around it
const start = cleanText.indexOf('{');
const end = cleanText.lastIndexOf('}');

if (start === -1 || end === -1) {
  throw new Error('Gemini did not return valid JSON');
}

cleanText = cleanText.substring(start, end + 1);

// Parse Gemini JSON
let ai;

try {
  ai = JSON.parse(cleanText);
} catch (error) {
  throw new Error(
    'Could not parse Gemini JSON: ' + error.message
  );
}

// Convert dates to PostgreSQL format: YYYY-MM-DD
function normalizeDate(date) {
  if (!date) return null;

  date = String(date).trim();

  // Already YYYY-MM-DD
  if (/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    return date;
  }

  // DD/MM/YYYY
  let match = date.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);

  if (match) {
    const [, day, month, year] = match;
    return `${year}-${month}-${day}`;
  }

  // DD-MM-YYYY
  match = date.match(/^(\d{2})-(\d{2})-(\d{4})$/);

  if (match) {
    const [, day, month, year] = match;
    return `${year}-${month}-${day}`;
  }

  // Try to handle dates such as 17/04/26
  match = date.match(/^(\d{2})\/(\d{2})\/(\d{2})$/);

  if (match) {
    const [, day, month, year] = match;
    return `20${year}-${month}-${day}`;
  }

  // If format is unknown, return original value
  return date;
}

// Get report date
const reportDate = normalizeDate(
  ai.report_date || ai.date || item.json.report_date
);

// Get user ID from the original request if Gemini didn't return it
let userId = ai.user_id;

if (!userId) {
  try {
    userId = $('Validate Request').first().json.user_id;
  } catch (error) {
    // Ignore if node is unavailable
  }
}

// Pull the OCR text from the upstream Parse OCR Result node
let ocrText = '';
try {
  ocrText = $('Parse OCR Result').first().json.ocr_text || '';
} catch (error) {
  // Ignore if node is unavailable
}

// Build final output with a nested `ai` object (downstream nodes read $json.ai.*)
const output = {
  user_id: userId,
  report_type: ai.report_type || 'Blood Test',
  report_date: reportDate,
  ocr_text: ocrText,
  ai: {
    summary: ai.summary || '',
    parameters: Array.isArray(ai.parameters) ? ai.parameters : [],
    important_findings: Array.isArray(ai.important_findings) ? ai.important_findings : [],
    follow_up: Array.isArray(ai.follow_up) ? ai.follow_up : [],
    uncertain_information: Array.isArray(ai.uncertain_information) ? ai.uncertain_information : []
  }
};

// IMPORTANT:
// n8n Code node must return an ARRAY of objects.
return [
  {
    json: output
  }
];

const rows = $input.all().map(i => i.json);
const first = rows[0];
const report = Array.isArray(first) ? first[0] : first;
const prior = $('Parse AI JSON').first().json;
const params = (prior.ai.parameters || []).map(p => ({
  report_id: report.report_id,
  user_id: prior.user_id,
  name: p.name,
  value: p.value,
  unit: p.unit,
  reference_range: p.reference_range,
  status: p.status || 'unknown',
  measured_date: report.report_date
}));
return [{ json: { report, params, ai: prior.ai } }];
